      "memory_value": "记忆内容",
      "importance": 1-10 的重要性评分
    }
  ]
}

**记忆提取规则：**
- 从用户消息中提取关键信息（姓名、年龄、兴趣、爱好等）
- 每条记忆要简洁明确
- 重要性评分：9-10=非常重要（年龄、姓名），7-8=重要（兴趣、爱好），5-6=一般
- 如果没有值得记录的信息，memories 可以是空数组`;

return {
  json: {
    systemPrompt,
    userMessage: message,
    metadata: {
      mode: 'normal',
      intentType: 'chat',
      age: age
    }
  }
};

// 获取 AI Agent (chat) 的响应
const chatResponse = $input.item.json;

// 提取前面节点的 metadata
let metadata = {};
const promptNodes = ['苏格拉底模式Prompt', '心理安全模式Prompt', '正常对话模式Prompt', '提取图片生成上下文'];

for (const nodeName of promptNodes) {
  try {
    const node = $(nodeName);
    if (node && node.item && node.item.json && node.item.json.metadata) {
      metadata = node.item.json.metadata;
      break;
    }
  } catch (e) {
    // 节点不存在，继续
  }
}

// 提取 AI 回复文本
let aiOutput = '';
let directResponse = null;

// 检查是否有直接响应（图片生成模式）
try {
  const imageGenNode = $('提取图片生成上下文');
  if (imageGenNode && imageGenNode.item && imageGenNode.item.json && imageGenNode.item.json.response) {
    directResponse = imageGenNode.item.json.response;
  }
} catch (e) {
  // 节点不存在或没有直接响应
}

if (directResponse) {
  // 使用直接响应（图片生成模式）
  aiOutput = directResponse;
} else if (chatResponse.output) {
  aiOutput = chatResponse.output;
} else if (chatResponse.text) {
  aiOutput = chatResponse.text;
} else if (typeof chatResponse === 'string') {
  aiOutput = chatResponse;
} else {
  aiOutput = JSON.stringify(chatResponse);
}

// 尝试解析 JSON 格式的回复
let parsedResponse;
try {
  // 尝试直接解析
  parsedResponse = JSON.parse(aiOutput);
} catch (e) {
  // 如果解析失败，尝试提取 JSON 部分（可能包含 markdown 代码块）
  const jsonMatch = aiOutput.match(/```json\s*([\s\S]*?)\s*```/) || aiOutput.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    try {
      parsedResponse = JSON.parse(jsonMatch[1] || jsonMatch[0]);
    } catch (e2) {
      // 如果还是失败，按原格式处理
      parsedResponse = {
        response: aiOutput,
        memories: []
      };
    }
  } else {
    // 没有找到 JSON，按原格式处理
    parsedResponse = {
      response: aiOutput,
      memories: []
    };
  }
}

// 构建返回数据 - 返回 Edge Function 需要的字段
const result = {
  response: parsedResponse.response || aiOutput,
  intentType: metadata.intentType || 'chat',
  mode: metadata.mode || 'normal',
  memories: parsedResponse.memories || []
};

// 如果有 metadata，添加到结果中
if (metadata) {
  result.metadata = metadata;
}

// 如果有 generationData，添加到结果中
if (metadata.generationData) {
  result.generationData = metadata.generationData;
}

return {
  json: result
};

// 准备图片生成所需的数据
const responseData = $input.item.json;
const webhookData = $('Webhook').first().json.body;

// 提取生成数据
const generationData = responseData.generationData || {};

// 构建完整的生成请求数据
const imageGenRequest = {
  userId: webhookData.userId || generationData.userId,
  characterId: webhookData.character.id || generationData.characterId,
  conversationId: webhookData.conversationId || generationData.conversationId,
  prompt: generationData.prompt || responseData.metadata?.image_prompt,
  theme: generationData.theme || responseData.metadata?.image_theme,
  style: generationData.style || responseData.metadata?.image_style,
  emotion: generationData.emotion || responseData.metadata?.image_emotion,
  userDescription: generationData.userDescription || generationData.theme,
  character: webhookData.character,
  startTime: Date.now()
};

return {
  json: imageGenRequest
};

// 处理 API 响应
const inputData = $('图片生成').first().json;
const requestData = $('准备图片生成数据').item.json;
const prefixUrl = "https://riwghatatpylyrejmlvi.supabase.co/storage/v1/object/public/";

// 检查是否有错误
if (inputData.error) {
  console.error('[ImageGen] API Error:', inputData.error);

  return {
    json: {
      success: false,
      error: inputData.error,
      userId: requestData.userId,
      conversationId: requestData.conversationId,
      prompt: requestData.prompt,
      retryCount: 0
    }
  };
}

// 提取图片 URL
let imageUrl = '';
let revisedPrompt = '';

if (inputData.data && inputData.data.length > 0) {
  imageUrl = prefixUrl + $input.first().json.Key;
  revisedPrompt = inputData.data[0].revised_prompt || requestData.prompt;
} else if (inputData.url) {
  imageUrl = prefixUrl + $input.first().json.Key;
}

// 计算生成时间
const generationTime = Math.round((Date.now() - requestData.startTime) / 1000);

// 构建图片记录
const imageRecord = {
  user_id: requestData.userId,
  character_id: requestData.characterId,
  conversation_id: requestData.conversationId,
  image_url: imageUrl,
  prompt: revisedPrompt,
  style: requestData.style,
  emotion: requestData.emotion,
  user_description: requestData.userDescription,
  metadata: {
    model: 'dall-e-3',
    generation_time: generationTime,
    api_provider: 'openai',
    original_prompt: requestData.prompt
  },
  is_favorite: false,
  is_deleted: false
};

return {
  json: {
    success: true,
    imageRecord: imageRecord,
    imageUrl: imageUrl,
    generationTime: generationTime
  }
};

// 错误处理逻辑
const errorData = $input.item.json;
const retryCount = errorData.retryCount || 0;
const maxRetries = 2;

// 记录错误日志
const errorLog = {
  type: 'image_generation_api_error',
  userId: errorData.userId,
  conversationId: errorData.conversationId,
  error: errorData.error,
  prompt: errorData.prompt,
  retryCount: retryCount,
  timestamp: new Date().toISOString()
};

console.error('[ImageGen] Error Log:', JSON.stringify(errorLog, null, 2));

// 判断是否需要重试
if (retryCount < maxRetries) {
  return {
    json: {
      shouldRetry: true,
      retryCount: retryCount + 1,
      userId: errorData.userId,
      conversationId: errorData.conversationId,
      prompt: errorData.prompt,
      error: errorData.error
    }
  };
} else {
  // 达到最大重试次数，记录最终失败
  return {
    json: {
      shouldRetry: false,
      finalError: true,
      userId: errorData.userId,
      conversationId: errorData.conversationId,
      error: errorData.error,
      errorLog: errorLog
    }
  };
}

// 子任务 5.2: 实现图片记录构建
// 从"处理 API 响应"节点获取数据
const responseData = $input.first().json;

// 检查是否成功
if (!responseData.success || !responseData.imageRecord) {
  console.error('[ImageGen] No image record to store');
  return {
    json: {
      error: 'No image record available',
      skip: true
    }
  };
}

// 获取完整的图片记录
const imageRecord = responseData.imageRecord;

// 确保所有必需字段都存在
const requiredFields = ['user_id', 'character_id', 'conversation_id', 'image_url', 'prompt', 'style', 'emotion', 'user_description'];
const missingFields = requiredFields.filter(field => !imageRecord[field]);

if (missingFields.length > 0) {
  console.error('[ImageGen] Missing required fields:', missingFields);
  return {
    json: {
      error: `Missing required fields: ${missingFields.join(', ')}`,
      skip: true
    }
  };
}

// 构建完整的图片记录对象（包含所有必需字段）
const completeImageRecord = {
  user_id: imageRecord.user_id,
  character_id: imageRecord.character_id,
  conversation_id: imageRecord.conversation_id || null,
  image_url: imageRecord.image_url,
  thumbnail_url: imageRecord.thumbnail_url || null,
  prompt: imageRecord.prompt,
  style: imageRecord.style,
  emotion: imageRecord.emotion,
  user_description: imageRecord.user_description,
  metadata: imageRecord.metadata || {
    model: 'dall-e-3',
    generation_time: responseData.generationTime || 0,
    api_provider: 'openai'
  },
  is_favorite: false,
  is_deleted: false
};

console.log('[ImageGen] Image record built successfully:', {
  user_id: completeImageRecord.user_id,
  conversation_id: completeImageRecord.conversation_id,
  image_url: completeImageRecord.image_url.substring(0, 50) + '...'
});

return {
  json: completeImageRecord
};

// 记录插入成功
const insertResult = $input.item.json;

console.log('[ImageGen] Image record inserted successfully:', {
  id: insertResult.id,
  user_id: insertResult.user_id,
  conversation_id: insertResult.conversation_id,
  image_url: insertResult.image_url ? insertResult.image_url.substring(0, 50) + '...' : 'N/A',
  created_at: insertResult.created_at
});

// Realtime 通知会自动触发，无需额外操作
console.log('[ImageGen] Realtime notification will be triggered automatically');

return {
  json: {
    success: true,
    message: 'Image record stored and notification sent',
    imageId: insertResult.id,
    userId: insertResult.user_id,
    conversationId: insertResult.conversation_id
  }
};

// 处理 Supabase 插入错误
const errorData = $input.item.json;

// 记录详细错误日志
const errorLog = {
  type: 'image_storage_error',
  error: errorData.error || errorData,
  timestamp: new Date().toISOString()
};

console.error('[ImageGen] Supabase Insert Error:', JSON.stringify(errorLog, null, 2));

// 不阻塞流程，只记录错误
return {
  json: {
    success: false,
    error: 'Failed to store image record',
    errorLog: errorLog
  }
};

// 获取 Edge Function 传递的完整上下文数据
const webhookData = $('Webhook').first().json.body;
const { message, userProfile, character, history } = webhookData;

// 从历史对话中提取已收集的信息
let context = {
  theme: null,
  style: null,
  emotion: null
};

// 分析最近的对话历史，提取已收集的信息
if (history && history.length > 0) {
  const recentMessages = history.slice(-10);

  // 从 metadata 中提取已收集的信息
  for (let i = recentMessages.length - 1; i >= 0; i--) {
    const msg = recentMessages[i];
    if (msg.metadata) {
      if (msg.metadata.image_theme && !context.theme) {
        context.theme = msg.metadata.image_theme;
      }
      if (msg.metadata.image_style && !context.style) {
        context.style = msg.metadata.image_style;
      }
      if (msg.metadata.image_emotion && !context.emotion) {
        context.emotion = msg.metadata.image_emotion;
      }
    }
  }
}

// 构建对话历史文本
let conversationHistory = '';
if (history && history.length > 0) {
  conversationHistory = history.slice(-6).map(m => `${m.role}: ${m.content}`).join('\n');
}

